    cmin, cmax = min(c for r,c in pts), max(c for r,c in pts)
    out = [row[:] for row in grid]
    # In the dot-coded example, repeated dots mark full horizontal/vertical strokes.
    if fg == 0:
        for r in range(h):
            cs = [c for rr,c in pts if rr == r]
            if len(cs) >= 2:
