            if len(rs) >= 2:
                for r in range(rmin, rmax + 1):
                    if out[r][c] == bg: out[r][c] = 2
        return out
    # Bridge single-cell interruptions in horizontal or vertical strokes.
    for r in range(h):
        for c in range(1, w-1):
